impl<X: UserData> RunWith<X> {
    /// This node and every node under it with each `user_data` at `Y`'s default; every other field
    /// moves as it is.
    #[must_use = "the tree moves into the one returned; dropping it drops the tree"]
    pub fn into_user_data<Y>(mut self) -> RunWith<Y>
    where
        Y: UserData,
    {
        RunWith {
            content: officekit_markup_base::into_user_data_list(
                self.content,
                RunContentWith::into_user_data,
            ),
            properties: officekit_markup_base::into_user_data_optional(
                &mut self.properties,
                RunPropertiesWith::into_user_data,
            ),
            unknown: self.unknown,
            user_data: Default::default(),
            w_properties: officekit_markup_base::into_user_data_optional(
                &mut self.w_properties,
                super::wordprocessing::RunPropertiesWith::into_user_data,
            ),
        }
    }

    /// What a read found that the schemas do not declare; `None` when it found nothing.
    #[must_use = "this only returns the value"]
    pub fn unknown(&self) -> Option<&officekit_markup_base::Unknown> {
        self.unknown.as_deref()
    }

    /// The unknown content to change, an empty record put in place when the node holds none.
    pub fn unknown_mut(&mut self) -> &mut officekit_markup_base::Unknown {
        self.unknown.get_or_insert_default()
    }

    /// This node's attributes, copied, with no declared child and no unknown content.
    #[must_use = "this returns a copy; the node is unchanged"]
    pub fn without_children(&self) -> Self {
        Self::default()
    }
}

