impl From<String> for TopBottom {
    fn from(text: String) -> Self {
        match Self::parse(&text) {
            Ok(member) if officekit_markup_base::spells(&member, &text) => Self::Member(member),
            Ok(_) | Err(_) => Self::Spelled(text.into_boxed_str()),
        }
    }
}

